{
   "title": "MarketCalendar",
   "description": "Dataclass containing information about market holidays and shortened days.",
   "type": "object",
   "properties": {
      "market-half-days": {
         "items": {
            "format": "date",
            "type": "string"
         },
         "title": "Market-Half-Days",
         "type": "array"
      },
      "market-holidays": {
         "items": {
            "format": "date",
            "type": "string"
         },
         "title": "Market-Holidays",
         "type": "array"
      }
   },
   "required": [
      "market-half-days",
      "market-holidays"
   ]
}

{
   "title": "MarketSession",
   "description": "Dataclass representing the current, next, and previous sessions.",
   "type": "object",
   "properties": {
      "close-at": {
         "anyOf": [
            {
               "format": "date-time",
               "type": "string"
            },
            {
               "type": "null"
            }
         ],
         "default": null,
         "title": "Close-At"
      },
      "close-at-ext": {
         "anyOf": [
            {
               "format": "date-time",
               "type": "string"
            },
            {
               "type": "null"
            }
         ],
         "default": null,
         "title": "Close-At-Ext"
      },
      "instrument-collection": {
         "title": "Instrument-Collection",
         "type": "string"
      },
      "open-at": {
         "anyOf": [
            {
               "format": "date-time",
               "type": "string"
            },
            {
               "type": "null"
            }
         ],
         "default": null,
         "title": "Open-At"
      },
      "start-at": {
         "anyOf": [
            {
               "format": "date-time",
               "type": "string"
            },
            {
               "type": "null"
            }
         ],
         "default": null,
         "title": "Start-At"
      },
      "next-session": {
         "anyOf": [
            {
               "$ref": "#/$defs/MarketSessionSnapshot"
            },
            {
               "type": "null"
            }
         ],
         "default": null
      },
      "previous-session": {
         "anyOf": [
            {
               "$ref": "#/$defs/MarketSessionSnapshot"
            },
            {
               "type": "null"
            }
         ],
         "default": null
      },
      "state": {
         "$ref": "#/$defs/MarketStatus"
      }
   },
   "$defs": {
      "MarketSessionSnapshot": {
         "description": "Dataclass containing information about the upcoming or previous market session.",
         "properties": {
            "close-at": {
               "format": "date-time",
               "title": "Close-At",
               "type": "string"
            },
            "close-at-ext": {
               "anyOf": [
                  {
                     "format": "date-time",
                     "type": "string"
                  },
                  {
                     "type": "null"
                  }
               ],
               "default": null,
               "title": "Close-At-Ext"
            },
            "instrument-collection": {
               "title": "Instrument-Collection",
               "type": "string"
            },
            "open-at": {
               "format": "date-time",
               "title": "Open-At",
               "type": "string"
            },
            "session-date": {
               "format": "date",
               "title": "Session-Date",
               "type": "string"
            },
            "start-at": {
               "format": "date-time",
               "title": "Start-At",
               "type": "string"
            }
         },
         "required": [
            "close-at",
            "instrument-collection",
            "open-at",
            "session-date",
            "start-at"
         ],
         "title": "MarketSessionSnapshot",
         "type": "object"
      },
      "MarketStatus": {
         "description": "Contains the valid market status values.",
         "enum": [
            "Open",
            "Closed",
            "Pre-market",
            "Extended"
         ],
         "title": "MarketStatus",
         "type": "string"
      }
   },
   "required": [
      "instrument-collection",
      "state"
   ]
}

